const strip = (value: string) =>
  value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter(Boolean);

/**
 * Does the place we found actually carry the name the model gave us?
 *
 * A text search almost always returns *something*, so "the id was found"
 * proves nothing: an invented name quietly resolves to the nearest real bar,
 * and we would show a stranger's place under a made-up title, with its photo
 * and its Maps link. Identity is only attached when the names line up.
 */
function namesMatch(modelName: string, foundName: string): boolean {
  const wanted = strip(modelName);
  const found = strip(foundName);
  if (wanted.length === 0 || found.length === 0) return false;

  const noise = new Set(['bar', 'cafe', 'café', 'restaurant', 'coffee', 'the', 'and']);
  const core = wanted.filter((word) => !noise.has(word));
  const needle = core.length > 0 ? core : wanted;

  const hits = needle.filter((word) => found.some((other) => other.startsWith(word))).length;
  return hits / needle.length >= 0.6;
}

/**
 * "Mother Roaster (Talat Noi)" never matches anything in Places: the bracketed
 * district is the model's annotation, not part of the name.
 */
function cleanName(name: string): string {
  return name
    .replace(/\s*[([].*?[)\]]\s*/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

async function resolveTripPlace(
  raw: RawTripPlace,
  city: string,
  anchors: string[],
  location?: CityLocation,
): Promise<TripPlace | null> {
  const name = cleanName(raw.n);
  const query = `${name} ${city}`;
  const hits = await getPlacesProvider().search(query, {});
  const match = hits.find((hit) => namesMatch(name, hit.name));

  let details = null;
  if (match) {
    details = await getPlacesProvider().details(match.placeId);
    if (location && (!details || !isInCity(details, location))) return null;

    // Spec 5: one place that shut down kills trust in all seven.
    if (details?.businessStatus && details.businessStatus !== 'OPERATIONAL') return null;

    /**
     * Quality 2 — review language. Measured and kept, but no longer used to
     * drop anything: in Da Nang and Bangkok even the places locals live in
     * collect English reviews, so an absolute threshold threw out the good
     * ones. It becomes useful as a relative term once ranking can compare a
     * place against the city's own median, not against a fixed number.
     */
  }

  return {
    placeId: match?.placeId ?? `unverified_${city}_${name}`,
    name: match?.name ?? name,
    area: raw.a,
    dayNight: raw.dn === 'night' ? 'night' : 'day',
    why: raw.w,
    orderTip: raw.o,
    mapsQuery: query,
    // The photo comes from details, not from the autocomplete row — the row
    // never carries one, which is why every card was a grey tile.
    photoUrl: details?.photoUrl ?? match?.photoUrl,
    photoAttribution: details?.photoAttribution ?? match?.photoAttribution,
    verified: Boolean(match),
    // Quality 6: kept so the card can own up to a low rating instead of
    // hoping the person does not notice it in Maps.
    rating: details?.rating,
    lat: details?.lat,
    lng: details?.lng,
    countryCode: details?.countryCode,
    wildcard: Boolean(raw.wild),
    // Spec 13: keep the reason a recommendation appeared, even if unused today.
    becauseOf: anchors[0],
    primaryType: details?.primaryType,
    types: details?.types,
    category: details && venueTypeOf(details) ? venueCategory(venueTypeOf(details)!) : categoryOf(details?.types),
  };
}

/**
 * Pass 1, cached. The pool is impersonal, so it is shared across everyone
 * travelling to that city — that is what makes the second trip cheap.
 */
async function candidatesFor(
  city: string,
  locale?: string,
  usage?: UsageSink,
  excluded: TripPlace[] = [],
  category?: Category,
  allowedTypes: VenueType[] = [],
  cityPlaceId?: string,
  recovery?: { keep: Candidate[]; excludeNames: string[] },
  /** Primary types of the person's saved places, e.g. cocktail_bar: the open base samples these first. */
  preferredPrimaryTypes: string[] = [],
): Promise<{ candidates: Candidate[]; fromCache: boolean }> {
  // A city search is one combined retrieval for all eligible types. Its pool
  // is shared by city and type set; categories never become parallel calls.
  const scope = allowedTypes?.length ? [...allowedTypes].sort().join(',') : 'all';
  // Existing food/nightlife pools remain reusable; outdoor retrieval has its
  // own version so future nature changes cannot invalidate unrelated caches.
  const version = allowedTypes.some(type => venueCategory(type) === 'nature') ? 'city-outdoors-v1' : 'city-verified-v3';
  const discovery = setting<string>('PROMPT_DISCOVERY');
  // Keep existing default pools; custom prompt revisions get a separate cache.
  const promptVersion = discovery === DISCOVERY_TEMPLATE ? '' : `:prompt-${createHash('sha256').update(discovery).digest('hex').slice(0, 16)}`;
  const cacheKey = `${cityPlaceId ?? city.toLowerCase()}:${version}:${scope}${promptVersion}`;
  const cutoff = new Date(Date.now() - CANDIDATES_TTL_DAYS * 86_400_000);
  const cached = recovery ? null : await CityCandidatesCollection.findOneAsync({
    city: cacheKey,
    createdAt: { $gte: cutoff },
  });
  const excludedNames = [...excluded.map(place => place.name), ...(recovery?.excludeNames ?? [])];

