import type { Place } from '/imports/domain/types';

/**
 * Places provider. The Google key never reaches the client:
 * autocomplete, details and photos are all proxied by the server.
 * That also gives us the shared place cache (spec 9.2) and quota control.
 */
export interface PlaceSuggestion {
  placeId: string;
  name: string;
  city: string;
  area?: string;
  /** Present when the source knows them — the map needs them to drop a pin. */
  lat?: number;
  lng?: number;
  photoUrl?: string;
  photoAttribution?: string;
  /**
   * True once the place has been turned into a seed event. Such a place stays
   * on the screen — it is part of the profile now — but it can no longer be
   * taken back, because events are append-only.
   */
  committed?: boolean;
  /** Transient billing token; persisted only until the selected prediction is
   * resolved to details, then discarded with the draft. */
  sessionToken?: string;
}

export interface CitySuggestion {
  placeId: string;
  /** What we show and what goes into the prompt: "Bangkok, Thailand". */
  label: string;
  /** Just the city: "Bangkok". */
  city: string;
}

/** A short-lived image URL returned by the Places Photo API. */
export interface PlacePhoto {
  url: string;
  attribution?: string;
}

/**
 * A place plus the transient bits we are allowed to read but not to keep:
 * Places terms limit how long third-party content may be cached, so review
 * text is used at enrichment time and never written to our collection.
 */
export interface PlaceDetails extends Place {
  reviewTexts?: string[];
}

export interface PlacesProvider {
  readonly kind: 'google' | 'open';
  /**
   * Autocomplete. sessionToken is the Places Autocomplete billing session;
   * `near` biases (does not restrict) the results towards a point.
   */
  search(query: string, opts: { sessionToken?: string; languageCode?: string; near?: { lat: number; lng: number } }): Promise<PlaceSuggestion[]>;
  /** Full details for enrichment and storage. */
  details(placeId: string, opts?: { sessionToken?: string }): Promise<PlaceDetails | null>;
  /** Fetch a current, displayable photo only when a card is actually visible. */
  photo(placeId: string): Promise<PlacePhoto | null>;
  /** Places around a city, for the map sheet. */
  nearby(city: string): Promise<PlaceSuggestion[]>;
  /**
   * Cities only. The trip city has to be a city: without this the field
   * happily accepts "opium bangkok" and the whole generation is built on it.
   */
  searchCities(query: string, sessionToken?: string, languageCode?: string): Promise<CitySuggestion[]>;
  /** Approximate city only; coordinates are never persisted. */
  cityNear(lat: number, lng: number): Promise<CitySuggestion | null>;
}
