import { OpenCitiesCollection, VenuesCollection, type OpenCity, type Venue } from '../collections';
import { coreWords, nameKey, nameSimilarity } from '/imports/domain/nameKey';
import type { CitySuggestion, PlaceDetails, PlacePhoto, PlacesProvider, PlaceSuggestion } from './provider';
import { googlePlaceIdFor, googlePlacesProvider } from './googleProvider';
import { reserveProviderRequest } from '../providerBudget';

/**
 * Places from our own venue base (Overture Maps open data) instead of Google.
 * Lookups, details, "is it new" and country cost nothing per request; the
 * only outside call is the venue's own website, once, for its preview image.
 */

const CITY_PREFIX = 'city_';
const NEAR_CITY_KM = 80;
const PHOTO_TIMEOUT_MS = 5000;
/** Below this a lookup returns nothing rather than a different place. */
const MIN_NAME_SIMILARITY = 0.75;

function km(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 12742 * Math.asin(Math.sqrt(h));
}

async function nearestCity(point: { lat: number; lng: number }): Promise<OpenCity | null> {
  const cities = await OpenCitiesCollection.find({}).fetchAsync();
  const best = cities.map(city => ({ city, d: km(point, city) })).sort((a, b) => a.d - b.d)[0];
  return best && best.d <= NEAR_CITY_KM ? best.city : null;
}

/** "Bar Leone Hong Kong, China" -> the Hong Kong city and the words left for the venue. */
async function splitCity(key: string): Promise<{ city: OpenCity | null; rest: string; placeWords: string[] }> {
  const cities = await OpenCitiesCollection.find({}).fetchAsync();
  for (const city of cities) {
    const words = [...nameKey(city.city).split(' '), ...nameKey(city.country).split(' ')];
    const cityKey = nameKey(city.city);
    if (` ${key} `.includes(` ${cityKey} `)) {
      const rest = ` ${key} `.replace(` ${cityKey} `, ' ').replace(` ${nameKey(city.country)} `, ' ').trim();
      return { city, rest, placeWords: words };
    }
  }
  return { city: null, rest: key, placeWords: [] };
}

const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function toSuggestion(venue: Venue): PlaceSuggestion {
  return { placeId: venue.venueId, name: venue.name, city: venue.city, lat: venue.lat, lng: venue.lng };
}

function cityDetails(city: OpenCity): PlaceDetails {
  return {
    placeId: city.placeId, name: city.city, city: city.city, country: city.country, countryCode: city.countryCode,
    lat: city.lat, lng: city.lng, types: ['locality', 'political'], primaryType: 'locality',
    tags: [], popularityScore: 0.5, source: 'open', verifiedAt: new Date(),
  };
}

function venueDetails(venue: Venue): PlaceDetails {
  return {
    placeId: venue.venueId, name: venue.name, city: venue.city, country: venue.country, countryCode: venue.countryCode,
    lat: venue.lat, lng: venue.lng, businessStatus: 'OPERATIONAL', types: venue.types, primaryType: venue.primaryType,
    tags: [], popularityScore: 0.5, source: 'open', verifiedAt: new Date(),
  };
}

/** The image a site publishes for link previews (og:image / twitter:image). */
async function previewImage(website: string): Promise<string | null> {
  const url = /^https?:\/\//i.test(website) ? website : `https://${website}`;
  const res = await fetch(url, {
    redirect: 'follow', signal: AbortSignal.timeout(PHOTO_TIMEOUT_MS),
    headers: { 'user-agent': 'Mozilla/5.0 (compatible; VergerBot/1.0)', accept: 'text/html' },
  });
  if (!res.ok || !(res.headers.get('content-type') ?? '').includes('html')) return null;
  const html = (await res.text()).slice(0, 300_000);
  const meta = /<meta[^>]+(?:property|name)=["'](?:og:image(?::secure_url)?|twitter:image)["'][^>]*>/i.exec(html)?.[0];
  const content = meta && /content=["']([^"']+)["']/i.exec(meta)?.[1];
  if (!content) return null;
  const image = new URL(content.replace(/&amp;/g, '&'), res.url).toString();
  // Logos and favicons make worse cards than a category placeholder.
  return /logo|favicon|icon|sprite/i.test(image) ? null : image;
}

export const openPlacesProvider: PlacesProvider = {
  kind: 'open',

  async search(query, opts) {
    const key = nameKey(query);
    if (!key) return [];
    let { city, rest, placeWords } = await splitCity(key);
    if (!city && opts.near) city = await nearestCity(opts.near);
    const wanted = rest || key;
    const words = coreWords(wanted, placeWords);
    const pattern = words.map(word => `(?=.*(?:^| )${escape(word)})`).join('');
    // Exact names first: in Bangkok hundreds of venues contain the word "us",
    // and "Bar Us" itself must not fall outside the fuzzy query's limit.
    const exact = await VenuesCollection.find({
      ...(city ? { city: city.city } : {}),
      $or: [{ nameKey: wanted }, { altKeys: wanted }, { compactKey: wanted.replace(/ /g, '') }],
    }, { limit: 20 }).fetchAsync();
    // Verifying a known name (no typing session) stops at an exact match; the
    // fuzzy scan below walks a whole city and is only worth it while typing.
    const fuzzy = exact.length && !opts.sessionToken ? [] : await VenuesCollection.find(
      {
        ...(city ? { city: city.city } : {}),
        $or: [
          { nameKey: new RegExp(`^${pattern}`) },
          { altKeys: new RegExp(`^${pattern}`) },
          // "Barro Negro" is stored as "BarroNegro".
          { compactKey: new RegExp(escape(words.join(''))) },
        ],
      },
      { limit: 80 },
    ).fetchAsync();
    const found = [...exact, ...fuzzy.filter(venue => !exact.some(e => e.venueId === venue.venueId))];

    // Compare what makes the name distinctive: "Bar Mauro" must not settle for
    // "Barbacoa Mauro y Mari" just because both contain "mauro".
    const filler = [...placeWords];
    const core = (value: string) => coreWords(value, filler).join(' ');
    const wantedCore = core(wanted);
    const wantsBar = /\b(bar|pub|cocktails?)\b/.test(wanted);
    const similarity = (name: string) => {
      if (name.replace(/ /g, '') === wanted.replace(/ /g, '')) return 1;
      const nameCore = core(name);
      // "De la Vie" shares the core of "De Vie" but loses to the exact name.
      if (nameCore.replace(/ /g, '') === wantedCore.replace(/ /g, '')) return 0.97;
      // Typing a name: a prefix of the distinctive part is a match.
      if (nameCore.startsWith(wantedCore)) return 0.9;
      return Math.max(nameSimilarity(wanted, name), nameSimilarity(wantedCore, nameCore));
    };
    return found
      .map(venue => {
        const barLike = /bar|pub|club|lounge|speakeasy|distill|brew|win/.test(venue.primaryType);
        // "Bar Nouveau" is a bar: "Le Nouveau" the restaurant is a different place.
        const score = Math.max(similarity(venue.nameKey), ...venue.altKeys.map(similarity)) - (wantsBar && !barLike ? 0.3 : 0);
        return { venue, score, rank: score + (venue.candidate ? 0.05 : 0) };
      })
      .filter(({ score }) => score >= MIN_NAME_SIMILARITY)
      .sort((a, b) => b.rank - a.rank)
      .slice(0, 6)
      .map(({ venue }) => toSuggestion(venue));
  },

  async searchCities(query) {
    const key = nameKey(query);
    const cities = await OpenCitiesCollection.find({}).fetchAsync();
    return cities
      .filter(city => nameKey(city.label).split(' ').some(word => word.startsWith(key.split(' ')[0] ?? '')) &&
        nameKey(city.label).includes(key))
      .slice(0, 6)
      .map((city): CitySuggestion => ({ placeId: city.placeId, label: city.label, city: city.city }));
  },

  async cityNear(lat, lng) {
    const city = await nearestCity({ lat, lng });
    return city ? { placeId: city.placeId, label: city.label, city: city.city } : null;
  },

  async details(placeId) {
    if (placeId.startsWith(CITY_PREFIX)) {
      const city = await OpenCitiesCollection.findOneAsync({ placeId });
      return city ? cityDetails(city) : null;
    }
    const venue = await VenuesCollection.findOneAsync({ venueId: placeId });
    return venue ? venueDetails(venue) : null;
  },

  /**
   * The venue's own preview image first (free, cached). Without one, and with
   * a Google key, Google's photo: finding the place_id and the photo reference
   * are free, the image itself is the one billed call ($0.007), and Google does
   * not allow caching it, so it is fetched each time a card is opened.
   */
  async photo(placeId): Promise<PlacePhoto | null> {
    const venue = await VenuesCollection.findOneAsync({ venueId: placeId },
      { fields: { venueId: 1, name: 1, lat: 1, lng: 1, website: 1, photoUrl: 1, googlePlaceId: 1 } });
    if (!venue) return null;
    let site = venue.photoUrl;
    if (site === undefined) {
      site = (venue.website ? await previewImage(venue.website).catch(() => null) : null) ?? '';
      await VenuesCollection.updateAsync({ venueId: placeId }, { $set: { photoUrl: site } });
    }
    if (site) return { url: site, attribution: hostOf(venue.website) };
    return googlePhoto(venue).catch(() => null);
  },

  async nearby(city) {
    const venues = await VenuesCollection.find(
      { city, primaryType: { $in: ['bar', 'cocktail_bar', 'pub', 'restaurant', 'wine_bar'] } },
      { sort: { confidence: -1 }, limit: 10 },
    ).fetchAsync();
    return venues.map(toSuggestion);
  },
};

async function googlePhoto(venue: Venue): Promise<PlacePhoto | null> {
  if (!process.env.GOOGLE_PLACES_KEY) return null;
  let googleId = venue.googlePlaceId;
  if (googleId === undefined) {
    await reserveProviderRequest('places');
    googleId = (await googlePlaceIdFor(venue.name, venue.lat, venue.lng)) ?? '';
    await VenuesCollection.updateAsync({ venueId: venue.venueId }, { $set: { googlePlaceId: googleId } });
  }
  if (!googleId) return null;
  // Photo metadata and media, as in the Google provider's own photo budget.
  await reserveProviderRequest('places-photo');
  await reserveProviderRequest('places-photo');
  return googlePlacesProvider.photo(googleId);
}

function hostOf(website?: string) {
  if (!website) return undefined;
  try { return new URL(/^https?:\/\//i.test(website) ? website : `https://${website}`).hostname.replace(/^www\./, ''); }
  catch { return undefined; }
}

