import { t } from '/imports/i18n';

/**
 * Platform adapter. Everything the UI needs from the host lives here, so a
 * native client replaces this one file (Linking, Clipboard, Geolocation)
 * instead of hunting calls across the screens.
 */

export const platform = {
  openUrl(url: string) {
    window.open(url, '_blank', 'noreferrer');
  },

  async copy(text: string): Promise<boolean> {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      return false;
    }
  },

  async share(data: { title: string; text: string }): Promise<'shared' | 'copied' | 'cancelled' | 'failed'> {
    try {
      if (navigator.share && (!navigator.canShare || navigator.canShare(data))) {
        // Call directly from the click handler to retain browser user activation.
        await navigator.share(data);
        return 'shared';
      }
    } catch (error) {
      // Dismissing the system sheet must not unexpectedly copy anything.
      if ((error as { name?: string } | null)?.name === 'AbortError') return 'cancelled';
    }
    return (await platform.copy(data.text)) ? 'copied' : 'failed';
  },

  async currentCity(): Promise<string | null> {
    // Spec 15: with no geolocation, fall back to the last trip's city.
    return null;
  },

  /** Hand the person a file. On native this becomes a share sheet. */
  download(filename: string, mime: string, contents: string) {
    const url = URL.createObjectURL(new Blob([contents], { type: mime }));
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  },

  prefersReducedMotion(): boolean {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  },
};

/** Spec 12 — export to Google Maps. */
export const maps = {
  place(query: string): string {
    return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
  },

  route(queries: string[]): string {
    const path = queries.map((q) => encodeURIComponent(q)).join('/');
    return `https://www.google.com/maps/dir/${path}`;
  },

  /**
   * A map file for Google My Maps.
   *
   * Google has no public API for writing into someone's saved places or their
   * My Maps — that simply does not exist, so a one-tap "put this in my Maps"
   * is not buildable. What does exist is import: My Maps reads KML, keeps the
   * folders, and lets each group carry its own pin colour. So the trip goes
   * across as three labelled groups — evening, day, and the punt — and it is
   * obvious at a glance where the places came from.
   */
  asKml(
    city: string,
    items: {
      name: string;
      area: string;
      why: string;
      orderTip: string;
      dayNight: string;
      wildcard?: boolean;
      mapsQuery: string;
      lat?: number;
      lng?: number;
    }[],
  ): string {
    const escape = (value: string) =>
      value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

    const groups: { id: string; title: string; colour: string; of: (i: any) => boolean }[] = [
      { id: 'evening', title: t('trip.night'), colour: 'ff483a5a', of: (i) => !i.wildcard && i.dayNight === 'night' },
      { id: 'day', title: t('trip.day'), colour: 'ff528f5c', of: (i) => !i.wildcard && i.dayNight === 'day' },
      { id: 'wild', title: t('trip.wildSection'), colour: 'ff4b83a8', of: (i) => Boolean(i.wildcard) },
    ];

    const placemark = (item: (typeof items)[number]) => {
      const description = [item.area, item.why, item.orderTip ? `→ ${item.orderTip}` : '']
        .filter(Boolean)
        .join('\n');

      const point =
        item.lat !== undefined && item.lng !== undefined
          ? `<Point><coordinates>${item.lng},${item.lat},0</coordinates></Point>`
          : `<address>${escape(item.mapsQuery)}</address>`;

      return `<Placemark><name>${escape(item.name)}</name><description>${escape(
        description,
      )}</description>${point}</Placemark>`;
    };

    const folders = groups
      .map((group) => {
        const members = items.filter(group.of);
        if (members.length === 0) return '';
        return `<Style id="${group.id}"><IconStyle><color>${group.colour}</color></IconStyle></Style>
<Folder><name>${escape(group.title)}</name>${members.map(placemark).join('')}</Folder>`;
      })
      .join('');

    return `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>${escape(
      t('trip.listHeader', { city }),
    )}</name>${folders}</Document></kml>`;
  },

  asText(city: string, items: { name: string; area: string; mapsQuery: string }[]): string {
    const lines = items.map((i) => `${i.name} — ${i.area}\n${maps.place(i.mapsQuery)}`);
    return [t('trip.listHeader', { city }), '', ...lines].join('\n');
  },
};

