// District from coordinates (TK-009): off by default, no network, no Meteor.
// Run: node --test scripts/area-from-coords.test.mjs
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
const exports = {};
const source = readFileSync(new URL('../app/imports/api/places/areaFromCoords.ts', import.meta.url), 'utf8');
const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
runInNewContext(code, { exports, console, fetch: () => assert.fail('network'), AbortSignal, Number, Map, Promise, setTimeout, Date });
const { pickArea, areaForPoint, areaFromCoordsEnabled, resetAreaCache } = exports;

test('flag: only AREA_SOURCE=coords turns it on', () => {
  assert.equal(areaFromCoordsEnabled({}), false);
  assert.equal(areaFromCoordsEnabled({ AREA_SOURCE: 'model' }), false);
  assert.equal(areaFromCoordsEnabled({ AREA_SOURCE: 'coords' }), true);
});

test('pickArea: most local field wins, noise and the city itself are skipped', () => {
  assert.equal(pickArea({ suburb: 'Hornstull', city_district: 'Södermalm' }, 'Stockholm'), 'Hornstull');
  assert.equal(pickArea({ quarter: 'International Financial Services Centre', city_district: 'North Dock C Ward 1986' }, 'Dublin'), 'International Financial Services Centre');
  assert.equal(pickArea({ city_district: 'North Dock C Ward 1986', borough: 'Manhattan Community Board 7' }, 'Dublin'), '');
  assert.equal(pickArea({ suburb: 'Wood Quay B ED', neighbourhood: 'Portobello' }, 'Dublin'), 'Portobello');
  assert.equal(pickArea({ borough: 'Manhattan', city: 'New York' }, 'New York'), 'Manhattan' === 'New York' ? '' : 'Manhattan');
  assert.equal(pickArea({ suburb: 'Kraków', city: 'Krakow' }, 'Kraków'), '');
  assert.equal(pickArea({ county: 'Kings County' }, 'New York'), '');
  assert.equal(pickArea(null, 'Rome'), '');
});

test('areaForPoint: reverse lookup, cached per cell, failures hidden and not cached', async () => {
  resetAreaCache();
  let calls = 0;
  const ok = async (url) => {
    calls++;
    assert.match(url, /zoom=14&lat=59\.3&lon=18\.1$/);
    return { ok: true, json: async () => ({ address: { suburb: 'Hornstull' } }) };
  };
  const env = { AREA_REVERSE_URL: 'http://geo.local/reverse' };
  assert.equal(await areaForPoint(59.3, 18.1, 'Stockholm', env, ok), 'Hornstull');
  assert.equal(await areaForPoint(59.30001, 18.1, 'Stockholm', env, ok), 'Hornstull');
  assert.equal(calls, 1);

  resetAreaCache();
  const down = async () => { throw new Error('offline'); };
  assert.equal(await areaForPoint(1, 2, 'X', env, down), '');
  assert.equal(await areaForPoint(1, 2, 'X', env, async () => ({ ok: true, json: async () => ({ address: { suburb: 'Back' } }) })), 'Back');
  assert.equal(await areaForPoint(Number.NaN, 2, 'X', env, down), '');
});

test('areaForPoint: the public server is called at most once a second', async () => {
  resetAreaCache();
  let now = 10_000;
  const slept = [];
  const fetchImpl = async () => ({ ok: true, json: async () => ({ address: { suburb: 'S' } }) });
  const sleep = async ms => { slept.push(ms); now += ms; };
  await areaForPoint(1, 1, 'C', {}, fetchImpl, () => now, sleep);
  await areaForPoint(2, 2, 'C', {}, fetchImpl, () => now, sleep);
  assert.equal(slept.length, 1);
  assert.equal(slept[0], 1100);
});
EOF
